mapper.select:
/* com.portal.user.policy.stp.StplatManageMapper.selectStplatList */ SELECT USE_STPLAT_ID AS useStplatId, USE_STPLAT_NM AS useStplatNm, USE_STPLAT_CN AS useStplatCn, INFO_PROVD_AGRE_CN AS infoProvdAgreCn, DATE_FORMAT(FRST_REGIST_PNTTM, '%Y-%m-%d') AS frstRegisterPnttm, FRST_REGISTER_ID AS frstRegisterId, DATE_FORMAT(LAST_UPDT_PNTTM, '%Y-%m-%d') AS lastUpdusrPnttm, LAST_UPDUSR_ID AS lastUpdusrId FROM LETTNSTPLATINFO WHERE 1 = 1
AND USE_STPLAT_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND USE_STPLAT_CN LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY USE_STPLAT_NM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.policy.stp.StplatManageMapper.selectStplatListTotCnt */ SELECT COUNT(*) AS totcnt FROM LETTNSTPLATINFO WHERE 1 = 1
AND USE_STPLAT_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND USE_STPLAT_CN LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.update:
/* com.portal.user.policy.stp.StplatManageMapper.updateStplatCn */
UPDATE LETTNSTPLATINFO
   SET USE_STPLAT_NM      = #{useStplatNm},
       USE_STPLAT_CN      = #{useStplatCn},
       INFO_PROVD_AGRE_CN = #{infoProvdAgreCn},
       LAST_UPDT_PNTTM    = SYSDATE(),
       LAST_UPDUSR_ID     = #{lastUpdusrId}
 WHERE USE_STPLAT_ID      = #{useStplatId}
